import { test, expect } from '@playwright/test';

test.describe('Loading Skeleton During API Data Fetch', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display loading skeleton while API data is fetching', async ({ page }) => {
    // Intercept the API call and delay it to observe the skeleton
    await page.route('**/api/data', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 2000));
      await route.continue();
    });

    // Trigger the data fetch
    await page.getByRole('button', { name: /load data/i }).click();

    // Verify skeleton is visible during loading
    const skeleton = page.getByTestId('loading-skeleton');
    await expect(skeleton).toBeVisible();

    // Verify skeleton has the appropriate loading class or animation
    const skeletonElement = await skeleton.evaluate((el) => {
      return window.getComputedStyle(el).opacity;
    });
    expect(skeletonElement).toBeDefined();

    // Wait for the skeleton to disappear
    await expect(skeleton).not.toBeVisible({ timeout: 3000 });

    // Verify actual data is displayed after loading
    const dataContent = page.getByText(/fetched data/i);
    await expect(dataContent).toBeVisible();
  });

  test('should show multiple skeleton items for list data', async ({ page }) => {
    // Intercept the API call with a delay
    await page.route('**/api/items', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 1500));
      await route.continue();
    });

    // Trigger the list data fetch
    await page.getByRole('button', { name: /load items/i }).click();

    // Verify multiple skeleton items are visible
    const skeletonItems = page.getByTestId('skeleton-item');
    const count = await skeletonItems.count();
    expect(count).toBeGreaterThan(0);

    // Verify each skeleton item is visible
    for (let i = 0; i < count; i++) {
      await expect(skeletonItems.nth(i)).toBeVisible();
    }

    // Wait for skeletons to be replaced with actual items
    await expect(skeletonItems.first()).not.toBeVisible({ timeout: 2000 });

    // Verify actual list items are now displayed
    const listItems = page.getByRole('listitem');
    await expect(listItems.first()).toBeVisible();
  });

  test('should hide skeleton and show error message on API failure', async ({ page }) => {
    // Intercept the API call and return an error
    await page.route('**/api/data', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 1000));
      await route.abort('failed');
    });

    // Trigger the data fetch
    await page.getByRole('button', { name: /load data/i }).click();

    // Verify skeleton is visible initially
    const skeleton = page.getByTestId('loading-skeleton');
    await expect(skeleton).toBeVisible();

    // Wait for skeleton to disappear
    await expect(skeleton).not.toBeVisible({ timeout: 2000 });

    // Verify error message is displayed
    const errorMessage = page.getByText(/error|failed/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should replace skeleton with actual content after successful API response', async ({ page }) => {
    // Intercept and delay the API response
    await page.route('**/api/user', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 1200));
      await route.continue();
    });

    // Click to fetch user data
    await page.getByRole('button', { name: /load profile/i }).click();

    // Verify skeleton is visible
    const skeleton = page.getByTestId('user-skeleton');
    await expect(skeleton).toBeVisible();

    // Verify skeleton elements (name, avatar, bio placeholders)
    const skeletonName = page.getByTestId('skeleton-name');
    const skeletonAvatar = page.getByTestId('skeleton-avatar');
    await expect(skeletonName).toBeVisible();
    await expect(skeletonAvatar).toBeVisible();

    // Wait for actual content to appear
    const userName = page.getByText(/john doe/i);
    await expect(userName).toBeVisible({ timeout: 2000 });

    // Verify skeleton is no longer visible
    await expect(skeleton).not.toBeVisible();

    // Verify actual user data is displayed
    const userBio = page.getByText(/software engineer/i);
    await expect(userBio).toBeVisible();
  });
});
